import org.junit.jupiter.api.Test;

class DistinctBindingSetHashTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void identityRowsDoNotRequireQuadraticEqualityChecks() {
		List<BindingSet> rows = new ArrayList<>();
		CountingBindingSet.comparisons = 0;
		for (int i = 0; i < 2_000; i++) {
			Value value = VF.createIRI("urn:node:" + i);
			CountingBindingSet row = new CountingBindingSet();
			row.addBinding("s", value);
			row.addBinding("o", value);
			assertEquals(28, row.hashCode(), "public BindingSet hash contract must not change");
			rows.add(row);
		}
		assertEquals(rows, distinct(rows));
		assertTrue(CountingBindingSet.comparisons < 20_000,
				"Identity-row membership compared " + CountingBindingSet.comparisons + " pairs");
	}

	@Test
	void comparesReorderedNamesAndDifferentImplementations() {
		Value a = VF.createIRI("urn:a");
		Value b = VF.createLiteral("b");
		BindingSet original = row("s", a, "o", b);
		BindingSet reordered = new ListBindingSet(List.of("o", "s"), b, a);
		QueryBindingSet query = new QueryBindingSet(original);
		ArrayBindingSet array = new ArrayBindingSet(new String[] { "o", "s" });
		array.setBinding("s", a);
		array.setBinding("o", b);
		BindingSet swapped = row("s", b, "o", a);
		List<BindingSet> result = distinct(List.of(original, reordered, query, array, swapped, original));
		assertEquals(List.of(original, swapped), result);
		assertSame(original, result.get(0));
		assertEquals(original.hashCode(), reordered.hashCode());
		assertEquals(original.hashCode(), query.hashCode());
		assertEquals(original.hashCode(), array.hashCode());
	}

	@Test
	void distinguishesNamesPartialRowsUnboundValuesAndMultipleVariables() {
		Value a = VF.createIRI("urn:a");
		BindingSet s = row("s", a);
		BindingSet o = row("o", a);
		BindingSet both = row("s", a, "o", a);
		BindingSet extra = row("s", a, "o", a, "extra", a);
		BindingSet empty = EmptyBindingSet.getInstance();
		List<BindingSet> input = List.of(s, new ListBindingSet(List.of("s", "o"), a, null),
				o, both, extra, empty, new MapBindingSet(),
				new ListBindingSet(List.of("s", "o"), null, null));
		assertEquals(List.of(s, o, both, extra, empty), distinct(input));
	}

	private static List<BindingSet> distinct(List<BindingSet> rows) {
		SingletonSet child = new SingletonSet();
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null) {
			@Override
			public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext context) {
				if (expr == child) {
					return bindings -> new CloseableIteratorIteration<>(rows.iterator());
				}
				return super.precompile(expr, context);
			}
		};
		try (CloseableIteration<BindingSet> result = strategy
				.precompile(new Distinct(child), new QueryEvaluationContext.Minimal(null))
				.evaluate(EmptyBindingSet.getInstance())) {
			return QueryResults.asList(result);
		}
	}

	private static MapBindingSet row(Object... values) {
		MapBindingSet row = new MapBindingSet();
		for (int i = 0; i < values.length; i += 2) {
			row.addBinding((String) values[i], (Value) values[i + 1]);
		}
		return row;
	}

	private static class CountingBindingSet extends MapBindingSet {
		private static int comparisons;

		@Override
		public boolean equals(Object other) {
			comparisons++;
			return super.equals(other);
		}
	}
}
